function handleInput() {
    ship.dx = 0;
    ship.dy = 0;
    let moving = false;
    if (keys.ArrowLeft) { ship.dx = -ship.speed; moving = true; }
    if (keys.ArrowRight) { ship.dx = ship.speed; moving = true; }
